CREATE TABLE IF NOT EXISTS agent_runs (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, member_id VARCHAR(36) NOT NULL, token_id VARCHAR(36) NOT NULL, device_id VARCHAR(36) NULL, agent VARCHAR(16) NOT NULL, workload VARCHAR(16) NOT NULL, started_at BIGINT NOT NULL, heartbeat_at BIGINT NOT NULL, last_request_at BIGINT NULL, ended_at BIGINT NULL, exit_code INT NULL, budget_units BIGINT DEFAULT 0 NOT NULL, max_concurrent INT DEFAULT 0 NOT NULL, paused BOOLEAN DEFAULT FALSE NOT NULL, charged_units BIGINT DEFAULT 0 NOT NULL, attempts BIGINT DEFAULT 0 NOT NULL, completed BIGINT DEFAULT 0 NOT NULL, contexts_truncated BOOLEAN DEFAULT FALSE NOT NULL, CONSTRAINT fk_agent_runs_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_agent_runs_member_id__id FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX run_member_page ON agent_runs (team_id, member_id, started_at, id);
CREATE INDEX run_team_page ON agent_runs (team_id, started_at, id);
CREATE INDEX run_retention ON agent_runs (heartbeat_at, ended_at);
